class Solution {
    public int countKDifference(int[] nums, int k) {
        int[] count = new int[101];
        int result = 0;
        for (int num : nums) {
            if (num - k >= 1) result += count[num - k];
            if (num + k <= 100) result += count[num + k];
            count[num]++;
        }
        return result;
    }
}

class Solution {
    public int countKDifference(int[] nums, int k) {
        int result = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (Math.abs(nums[i] - nums[j]) == k) result++;
            }
        }
        return result;
    }
}
